// Isolation test (OS-12) — construct UnitRegistry with its declared inputs and nothing
// else, then exercise every public operation. (Generated by new-object.py, rewritten for
// strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { isUnknown } from "../src/kernel/index.js";
import { UnitRegistry, type Unit } from "../src/catalog/index.js";

const unitOf = (r: UnitRegistry, id: string): Unit => {
  const u = r.unit(id);
  if (isUnknown(u)) throw new Error(`no unit ${id}`);
  return u;
};

describe("UnitRegistry in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new UnitRegistry({} as never)).toThrow();
  });

  it("unit answers differently when units differs", () => {
    const has = new UnitRegistry({ units: { u1: { difficulty: 1 } } });
    const lacks = new UnitRegistry({ units: { u9: { difficulty: 1 } } });
    expect(has.unit("u1")).not.toEqual(lacks.unit("u1"));
  });

  it("features answers differently when units differs", () => {
    const one = new UnitRegistry({ units: { u1: { difficulty: 1 } } });
    const seven = new UnitRegistry({ units: { u1: { difficulty: 7 } } });
    expect(one.features(unitOf(one, "u1"))).not.toEqual(seven.features(unitOf(seven, "u1")));
  });
});
